        assertThat(number >= aMinimum && number <= aMaximum, anErrorDescription);

        return number;
    }

    public static void assertThat(boolean aCondition, String anErrorDescription) {
        if (!aCondition) throw new RuntimeException(anErrorDescription);
    }

    // initialization

    private Validation() {
    }
